import React from 'react';
import { BrowserRouter as Router, Routes, Route, Navigate } from 'react-router-dom';
import { QueryClient, QueryClientProvider } from '@tanstack/react-query';
import Login from './pages/Login';
import CustomerDashboard from './pages/CustomerDashboard';
import WorkerDashboard from './pages/WorkerDashboard';

const queryClient = new QueryClient();

export default function App() {
    // Dynamic organization context (can be dynamic via subdomain or route params)
    const orgId = 'org_alpha'; 
    const machineId = 'MACH_01';

    return (
        <QueryClientProvider client={queryClient}>
            <Router>
                <Routes>
                    <Route path="/login" element={<Login orgId={orgId} />} />
                    <Route path="/customer" element={<CustomerDashboard orgId={orgId} />} />
                    <Route path="/worker" element={<WorkerDashboard orgId={orgId} machineId={machineId} />} />
                    <Route path="*" element={<Navigate to="/login" replace />} />
                </Routes>
            </Router>
        </QueryClientProvider>
    );
}
